code='''def transform(grid):
    out=[row[:] for row in grid]
    colors={v for row in grid for v in row if v!=7}
    marker=1 if colors=={9} else 9
    n=len(grid); m=len(grid[0]); launches=[]
    for r in range(n):
        for c in range(m):
            color=grid[r][c]
            if color==7: continue
            # Four V-shaped launchers. Ignore shapes touching left/right borders.
            if r+1<n and 0<c<m-2 and grid[r+1][c-1]==color and grid[r+1][c+1]==color:
                launches.append((r-5,c))
            if r>0 and 0<c<m-1 and grid[r-1][c-1]==color and grid[r-1][c+1]==color:
                launches.append((r+5,c))
            if c+1<m and r>0 and r+1<n and grid[r-1][c+1]==color and grid[r+1][c+1]==color:
                launches.append((r,c-5))
            if c>0 and r>0 and r+1<n and grid[r-1][c-1]==color and grid[r+1][c-1]==color:
                launches.append((r,c+5))
            # L launchers: the filled corner opposite the missing corner is the tip.
            if r+1<n and c+1<m:
                a=grid[r][c]==color; b=grid[r][c+1]==color; d=grid[r+1][c]==color; e=grid[r+1][c+1]==color
                if a and b and d and not e: launches.append((r-5,c-5))
                if a and b and e and not d: launches.append((r-5,c+6))
                if b and d and e and not a: launches.append((r+6,c+6))
                if a and d and e and not b: launches.append((r+6,c-5))
    for r,c in launches:
        if 0<=r<n and 0<=c<m: out[r][c]=marker
    # A projectile recolors the whole connected object it strikes.
    hits=[(r,c) for r,c in launches if 0<=r<n and 0<=c<m and grid[r][c]!=7]
    for hr,hc in hits:
        color=grid[hr][hc]; stack=[(hr,hc)]; seen=set()
        while stack:
            r,c=stack.pop()
            if (r,c) in seen: continue
            seen.add((r,c)); out[r][c]=marker
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                rr,cc=r+dr,c+dc
                if 0<=rr<n and 0<=cc<m and grid[rr][cc]==color: stack.append((rr,cc))
    return out
'''
